import React from "react";
import { AbsoluteFill } from '../remotionShim';
// Font Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type BannedStampProps = Record<string, any>;

const BannedStamp: React.FC<BannedStampProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 5,
  text = "BANNED",
  primaryColor = "#D32F2F", // Deep Red
  borderColor = "#D32F2F",
  fontSize = 200,
  borderWidth = 15,
}) => {
  useFontLoader(["Black Ops One"]);

  // Background handling
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Texture Filter ID
  const filterId = "stamp-texture";

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Texture Filter Definition */}
      <svg width="0" height="0" style={{ position: 'absolute' }}>
        <filter id={filterId}>
          {/* Create noise */}
          <feTurbulence 
            type="fractalNoise" 
            baseFrequency="0.8" 
            numOctaves="3" 
            result="noise" 
          />
          {/* Displace the source graphic by the noise */}
          <feDisplacementMap 
            in="SourceGraphic" 
            in2="noise" 
            scale="3" 
            xChannelSelector="R" 
            yChannelSelector="G" 
          />
        </filter>
      </svg>

      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          perspective: 1000,
        }}
      >
        <div
          style={{
            position: "relative",
            transform: `
              scale(1) 
              rotate(-5deg)
            `, // -5deg initial tilt for style
            border: `${borderWidth}px solid ${borderColor}`,
            borderRadius: borderWidth * 1.5,
            padding: `${fontSize * 0.2}px ${fontSize * 0.5}px`,
            color: primaryColor,
            fontFamily: "Black Ops One",
            fontSize: fontSize,
            textTransform: "uppercase",
            fontWeight: 900,
            lineHeight: 1,
            // Apply the rough ink filter
            filter: `url(#${filterId})`,
            // Add a subtle "multiply" blend mode if on light background for ink effect
            mixBlendMode: transparentBackground ? "normal" : "multiply", 
            boxShadow: `0 0 0 4px ${borderColor}20`, // faint double ring feel
            textAlign: "center",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            whiteSpace: "nowrap"
          }}
        >
          {text}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default BannedStamp;